const GPU_OK = await gpuBoot();
// (no WebGPU on the page: the loading screen says so and nothing of the game runs - no timers, no half-made game; the simulation worker
// never has a GPU and goes on)
if (!GPU_OK && !(typeof WorkerGlobalScope !== 'undefined' && typeof self !== 'undefined' && self instanceof WorkerGlobalScope)) {
  try { __bootSay('This game needs WebGPU'); setTimeout(() => __bootSay('Use a recent Chrome, Edge, Firefox or Safari'), 2500); } catch (e) { }
  console.error('No WebGPU here:', GPU.why);
  await new Promise(() => { });
}

