function sceneSkip(k) {
  if (k === SCENE.key) return true;
  try { const b = k.startsWith('bd_sw_') ? 'bd_' + k.slice(6) : k; return LOCAL_KEYS.includes(k) || LOCAL_KEYS.includes(b); } catch (e) { return false; }
}
const sceneEdOpen = () => { try { return !!NSKY.editor.TUNE.open; } catch (e) { return false; } };   // (NSKY: made later - not yet, no editor)
