  const iw = Math.round(im.width * s), ih = Math.round(im.height * s), ix = Math.round(ax + (aw - iw) / 2), iy = Math.round(ay + 8);
  ug.save(); ug.imageSmoothingEnabled = false; ug.drawImage(im, ix, iy, iw, ih); ug.restore();
