      lines[i].forEach((t, k) => drawText(ug, t, tx, y0 + lh * (k + 1), '#ffffff', ts, side === 'l' ? 'right' : 'left'));
      leader(side === 'l' ? tx + 4 : tx - 4, y0 + lh - 2, ix + q[2] * s, iy + q[3] * s);
      ly += lh * (lines[i].length + 1) + gap;
