  const sy = surfaceY(x);
  for (let i = 0; i < 14 + amt * 30; i++) spawnSpray(x + vehShipRnd(-15, 15), sy - 2, vehShipRnd(-110, 110) * amt, 1 + amt);
  const y = lv - vehShipRnd(6, 14);
