    spawnFlame(x + armShellRnd(-7, 7) * (0.6 + power * 0.5), oy + armShellRnd(-4, 6), armShellRnd(-22, 22) + sh.vx * 0.5, -armShellRnd(30, 150) * (0.6 + 0.45 * power), armShellRnd(1.15, 1.45), armShellRnd(2.6, 5) * (0.65 + 0.35 * power), armShellRnd(1.3, 1.9));
    flameLast().behind = true;
