  // above the deck: a few tongues licking up, and the column
  for (let i = 0; i < 8 * power + 3; i++) spawnFlame(x + armShellRnd(-5, 5), deck - armShellRnd(0, 6), armShellRnd(-14, 14) + sh.vx * 0.5, -armShellRnd(40, 120), armShellRnd(1.0, 1.3), armShellRnd(2, 3.8), armShellRnd(1.6, 2.2));
  for (let i = 0; i < 10 * power + 3; i++) spawnEmber(x + armShellRnd(-5, 5), deck - armShellRnd(0, 6), sh.vx * 0.4, 1.3);
  spawnSparks(x, deck - 3, 10 + 12 * power, 220);
  for (let i = 0; i < 6 + 8 * power; i++) spawnSmoke(x + armShellRnd(-5, 5), deck - armShellRnd(16, 34), { kind: 'blast', dark: 0.75, r: armShellRnd(3, 5.5) * (0.7 + 0.5 * power), grow: armShellRnd(3, 5), lift: 34, vx: armShellRnd(-8, 8) + sh.vx * 0.5, vy: armShellRnd(-55, -25), life: armShellRnd(7, 10), alpha: armShellRnd(0.5, 0.7) });
  gridExplosion(x, deck, 40 * power, 220 * power);
  for (let k = -20; k <= 20; k += DX) water.push(x + k, -2500 * power * (1 - Math.abs(k) / 22));
