  for (let i = 0; i < 14; i++) spawnFlame(x + armShellRnd(-4, 4), y + armShellRnd(-4, 4), armShellRnd(-90, 90), armShellRnd(-90, 30), 1.1, armShellRnd(3, 6), armShellRnd(3.5, 5));
  for (let i = 0; i < 8; i++) spawnSmoke(x + armShellRnd(-10, 10), y + armShellRnd(-8, 4), { kind: 'blast', dark: 0.6, r: armShellRnd(6, 10), lift: 25, vx: armShellRnd(-30, 30), alpha: armShellRnd(0.3, 0.45), life: armShellRnd(5, 8) });
