// into both: the fish in their schools' order, each its school's id)
defTable('seaSchools', null, { cols: schools, drawn: ['type', 'x', 'y', 'dir'], net: false, rows: rows => {
  const fish = [], S = rows.map((d, k) => { for (const f of (d && d.fish) || []) fish.push(Object.assign({}, f, { school: k + 1 })); return Object.assign({}, d, { _sa: d && d.sa_, _sk: d && d.sk_ }); });
  seaFish.fromPlainCols(seaFish.plainOfRows(fish)); return schools.plainOfRows(S); } });
defTable('seaFish', null, { cols: seaFish, drawn: ['school', 'x', 'y', 'dx', 'dy', 'face'], net: false });
defTable('seaSharks', () => sharks, { make: () => ({ x: 0, y: 0, dir: 1, speed: 20, turnT: 10, turn: 0, ph: 0 }) });
defTable('seaWhales', () => whales, { make: () => ({ x: 0, y: 0, dir: 1, speed: 10, turnT: 30, turn: 0, ph: 0, dy: 0, flee: 0 }) });
defTable('seaDeadFish', null, { cols: deadFish, rows: rows => deadFish.plainOfRows(rows) });   // (column tables since Nov 10, part 8 - 04-art-prep.js, 35-zz-sea-kills.js)
defTable('seaDeadBig', null, { cols: deadBig, rows: rows => deadBig.plainOfRows(rows) });
defTable('seaBlood', null, { cols: seaBlood, drawn: ['x', 'y', 'r', 't', 'life', 'sd', 'lob'], rows: rows => seaBlood.plainOfRows(rows), net: false });   // (Nov 1: column tables)
defTable('seaGore', null, { cols: seaGore, drawn: ['x', 'y', 's', 't', 'life', 'dark'], rows: rows => seaGore.plainOfRows(rows), net: false });
// the yachts (31-sailboats-buoys) - (Nov 10, part 8) a record table (04-zz-coltable.js): a row a yacht, held and walked as its handle, its
// fields as they were: her sails (sailsUp, furl, keepFurled), driven (drive), sinking, holed, burning, moored (anc, _moorX - 50-land-anchors.js),
// on a lake (lake); every civilian vehicle's (CIV_REC)
const sailboats = new ColTable(ColTable.rec('num: kind x y a av vx vy face sink lean ph t respawn hold sailsUp furl keepFurled drive ancHold _moorX _moorD _far avoid foam wreck under holed fireT',
  'txt: state', 'val: anc lake', ...CIV_REC));
defTable('sailboats', null, { cols: sailboats });
// the buoys (31-sailboats-buoys, built in 07-world-build): one off each harbour (buoys[k] is docks[k]'s), the red one mid-sea
defTable('buoys', null, { cols: buoys });   // (Nov 11: a record table - 31-sailboats-buoys.js)

