// (Oct 29: settings saved before six decks and the three sun sizes: the old deck 3 is deck 4 now, the old deck 4 deck 6; SUNSET
// SUN SIZE b becomes SUNRISE and SUNSET 1 + b. Marked with sky6, so it's done once)
function deckMigrate(o) {
  if (!o || o.sky6) return o;
  for (const b of ['dk', 'bl', 'bs', 'pf', 'pk', 'pl', 'par']) { if ((b + '4') in o) { o[b + '6'] = o[b + '4']; delete o[b + '4']; } if ((b + '3') in o) { o[b + '4'] = o[b + '3']; delete o[b + '3']; } }
  if ('sunbig' in o) { o.sunrise = o.sunset = 1 + o.sunbig; delete o.sunbig; }
  o.sky6 = 1; return o;
}
try { const o = deckMigrate(JSON.parse(localStorage.getItem('bd_sky_p') || 'null')); if (o) for (const k in o) if (k in P && !SCENE_KEYS.has(k) && typeof o[k] === typeof P[k]) P[k] = o[k]; } catch (e) { }
function saveP() { try { const o = { sky6: 1 }; for (const k in P) if (!SCENE_KEYS.has(k) && P[k] !== P_DEF[k]) o[k] = P[k]; localStorage.setItem('bd_sky_p', JSON.stringify(o)); } catch (e) { } }
