  let taut = 0; { let len = 0; for (let j = 0; j < n; j++) len += T.segs[j] * c; taut = smoothstep(0.72, 0.92, Math.hypot(J[n].x - J[0].x, J[n].y - J[0].y) / Math.max(1, len)); }
