  natureEdDraw();                                            // (the fish areas - 50-zz-nature)
  if (typeof bgEdDraw === 'function') bgEdDraw();            // (the backgrounds' boxes - 50-zz-backgrounds)
  wxaEdDraw();
  hplEdDraw();                                               // (the picked hand-placed plants - 50-zzzz-hand-plants.js)                                               // (the weather areas' lines - 50-zz-weather-areas)
  grpEdDraw();                                               // (GROUPING: the groups' frames - 50-zzz-objects-tab)
