  const picked = new Set([VE.sel, ...VE.more].filter(Boolean).map(P => P.v));
  for (const e of vehAll()) { if (picked.has(e.v) || !(e.v.placed != null || e.v._lifted)) continue; const bad = vehPlaceBad(e); if (bad) vehRing(e, bad); }   // (red where it can't be, as a structure)
