function vehRing(P, bad = '') {
  const [x0, x1, y0, y1] = vehBox(P), w = Math.max(2, Math.round(2 * dpr / PIXW)), g = w + 1;
  const L = Math.round(PX(x0)) - g, R = Math.round(PX(x1)) + g, T = Math.round(PY(y0)) - g, Bm = Math.round(PY(y1)) + g;
  if (R < 0 || L > VWP) return;
  // (four corner brackets on the vehicle's own box: the view's canvas fills, it doesn't stroke)
  const a = Math.max(4, Math.round(Math.min(R - L, Bm - T) * 0.3));
  for (const [col, q] of [['#04070f', w + 2], [bad ? '#ff5046' : '#ffffff', w]]) {   // (picked: white, as everything picked - user Nov 1; where it can't be: red)
    C.fillStyle = col; const o = (q - w) / 2;
    for (const [sx, sy] of [[-1, -1], [1, -1], [-1, 1], [1, 1]]) { const xc = sx < 0 ? L : R, yc = sy < 0 ? T : Bm; C.fillRect(Math.min(xc, xc - sx * a) - o, yc - q / 2, a + 2 * o, q); C.fillRect(xc - q / 2, Math.min(yc, yc - sy * a) - o, q, a + 2 * o); }
  }
  const tq = Math.max(1, Math.round(2 * dpr / PIXW));
  if (bad) { C.fillStyle = 'rgba(255,60,50,0.28)'; C.fillRect(L, T, R - L, Bm - T); }
  drawText(C, vehName(P), (L + R) / 2, T - 9 * tq, bad ? [255, 120, 110] : [255, 255, 255], tq, 'center');
  if (bad) drawText(C, bad, (L + R) / 2, (T + Bm) / 2, [255, 120, 110], tq, 'center');
}
