  if (armyFamOf(e.v) && ownOf(ARMY_PLACE[armyFamOf(e.v)].k, 0) !== e.v) { const k = armyTake(e.v); if (c.mode !== k) switchTo(0, k); cutTo(0); return; }   // (another team's or a placed one: player 0's now)
