      const k = STSW.on ? clamp((tS - STSW_T.LAND) / 0.25, 0, 1) : 1, sq = STSW.on ? Math.sin(k * Math.PI) * (1 - k) * 1.6 : 0;   // (landed: squashed, springing back)
