    const bob = Math.round(ARROW_BOB * Math.abs(Math.sin(time * 3.4)));
    pxArrow(X + dx, Y - bob, B, ARROW_COL.to, 0, pop);
    // its label over the bounce: the name; for sale, the price and how to buy it (or NO FUNDS)
    const lines = [[T.name, '#ffffff']];
    if (T.price != null) { const broke = story.coins < T.price; lines.push(['$ ' + T.price, '#ffd23a']); lines.push(broke ? ['NO FUNDS', '#ff6a5a'] : [storyBuyHint(), '#7fe08a']); }
    else if (T.market) lines.push([storyBuyHint().replace('PURCHASE', 'SELL GOODS'), '#7fe08a']);   // (a market: PRESS A TO SELL GOODS)
    let ly = Y - 7 * B - ARROW_BOB - 6 - lines.length * 16;
    ug.globalAlpha = pop;
