    const cur = L.find(q => q.cur), a = w(STSW.from[0], STSW.from[1]), b = cur ? w(cur.wx, cur.wy) : a;
    const ax = a.X, ay = a.Y - ARROW_GAP, bx = b.X, by = b.Y - ARROW_GAP, lift = Math.max(60, Math.hypot(bx - ax, by - ay) * 0.35);
