    ug.fillStyle = '#fff1c8'; ug.fillRect(Math.round(a.X) + 1, Math.round(a.Y) + 1, Math.max(1, Math.round(b.X - a.X) - 2), Math.max(1, Math.round((b.Y - a.Y) * 0.4)));
