const tropArt = {};
function tropPic(n) {
  const c0 = tropArt[n]; if (c0) return c0;
  const t = TROP[n], s = img.tropical; if (!t || !s || !s.width) return null;
  const A = TROP_CHIMNEY[n], ch = A && A.add ? img.chimney : null;
  if (A && A.add && !(ch && ch.width)) return null;           // (its chimney's picture not there yet)
  const up = ch ? Math.max(0, ch.height - A.add[1]) : 0;      // (the picture grows up by what of the chimney stands over its top)
  const c = makeCanvas(t.w, t.h + up);
  c.getContext('2d').drawImage(s, t.x, t.y, t.w, t.h, 0, up, t.w, t.h);
  c._m = t.m; c._name = n; c._chim = A ? (ch ? [A.add[0], 0] : A.top) : null;
  c._under = ch ? { P: ch, x: Math.round(A.add[0] - ch.width / 2), y: up + A.add[1] - ch.height } : null;   // (the user's chimney, behind the roof: the thatch over its foot)
  c._door = t.door ? [t.door[0], t.door[1] + up, t.door[2], t.door[3] + up] : null;   // (its door, marked by eye - gen/tropical/prep.py DOORS: the gate covers it)
  c._flag = flagCut(c, n, up);
  c._gate = t.gate && c._door ? gateCut(c._door) : null;
  const cuts = []; if (c._flag) cuts.push([c._flag.x, c._flag.y, c._flag.x + c._flag.w, c._flag.y + c._flag.h]); if (c._gate) cuts.push(c._door.slice());
  c._cuts = cuts.length ? cuts : null;
  return (tropArt[n] = c);
}
/* ---- PAINTED GATES (user Nov 2 11:53: "The gate must be red like the image, and should open UP, not down. And the fire truck
   must be masked inside so it feels like its 'leaving' the fire station"). A vehicle door (prep.py DOORS, `gate`) is taken out of
   its picture as the building is drawn (its _cuts): the door's own pixels are the gate (drawStrGate: a part of the picture, in front of
   what's inside, rolled up into the lintel), and the hole left shows the dark inside (STR_INSIDE, drawn behind the building - strStillDraw),
   behind the vehicles. A vehicle at home in it is drawn only where the building doesn't hide it - outside the building or through the door
   (strMaskBox - the things' shader, 45-zz-things-gpu.js). ---- */
const STR_INSIDE = [30, 24, 26];
// the gate: the door's place in its picture's texels [x, y, w, h]
function gateCut(D) { const [x0, y0, x1, y1] = D; return [x0, y0, x1 - x0, y1 - y0]; }
// an enclosed structure's painted gate, in the world: { x0, x1, top, foot } (null: none)
function strGateBox(o, B) {
  if (!B.P || !B.P._gate || !STR_KINDS[o.k].enclosed) return null;
  const D = B.P._door, kx = (B.x1 - B.x0) / B.P.width, ky = (B.foot - B.top) / B.P.height;
  const x0 = o.flip ? B.x1 - D[2] * kx : B.x0 + D[0] * kx;
  return { x0, x1: x0 + (D[2] - D[0]) * kx, top: B.top + D[1] * ky, foot: B.top + D[3] * ky };
}
// a vehicle at home in an enclosed structure with a painted gate and inside its walls: what the building doesn't hide of it (engine
// part 5: as numbers the things' shader tests - 45-zz-things-gpu.js) - seen where it's outside the building's columns X0..X1, or
// in its door's opening gx0..gx1 from gt down: [X0, X1, gx0, gx1, gt] on the screen, or null (not at home in one)
function strMaskBox(v, half) {
  if (!LAND) return null;
  for (const o of strsUsed()) {
    if (o.id !== v.hb && o.id !== v.berth) continue;
    const B = strBox(o); if (v.x + half <= B.x0 || v.x - half >= B.x1) continue;
    const G = strGateBox(o, B); if (!G) continue;
    return [Math.round(PX(B.x0)), Math.round(PX(B.x1)), Math.round(PX(G.x0)), Math.round(PX(G.x1)), Math.round(PY(G.top))];
  }
  return null;
}
// (user Nov 8 17:46: "you should not be able to capture something that's hidden in the hangar") a point inside an enclosed structure's
// walls (a hangar, a fire or police station - what keeps its vehicles out of sight) or a harbour's marine hangar (inHangar): hidden there
function strHides(x, y) {
  if (inHangar(x, y)) return true;
  if (!LAND) return false;
  for (const o of strsUsed()) {
    if (!(STR_KINDS[o.k] || {}).enclosed) continue;
    const B = strBox(o); if (x > B.x0 && x < B.x1 && y > B.top && y < B.foot) return true;
  }
  return false;
}
/* ---- FLAGS (user Nov 2: "Every time an object has a flag (e.g. school) it has to be dynamic and move with the current wind").
   A picture's flag painted in its art: its cloth's box (picture pixels: left, top, right, bottom - the pole left out) and the
   side its hoist is on (-1 left, 1 right). The cloth is taken out of the building as it's drawn (tropPic's _cuts; the pole stays) and drawn waving
   (strFlagDraw): each pixel column of it shifted up or down by a travelling sine, faster and wider as the wind grows (windAt),
   drooping a little in a calm; flown downwind (mirrored about its hoist when the wind blows the other way). One rule for every
   flag on every structure's picture. ---- */
const TROP_FLAGS = {
  school: { box: [183, 29, 200, 47], hoist: -1 },
  'fire-station': { box: [92, 14, 102, 25], hoist: 1 },
};
// (its cloth's box in the picture's texels - taken out of the building as it's drawn, its columns drawn waving from the same texels)
function flagCut(c, n, up) {
  const F = TROP_FLAGS[n]; if (!F) return null;
  const [x0, y0, x1, y1] = F.box;
  return { x: x0, y: y0 + up, w: x1 - x0, h: y1 - y0, hoist: F.hoist };
}
