    d.innerHTML = '<div style="background:#0f1420;border:2px solid #ffd23a;border-radius:6px;padding:14px 18px;text-align:center;min-width:280px">'
      + '<div style="margin-bottom:4px">UNSAVED CHANGES</div><div style="color:#7a8294;margin-bottom:12px">SAVE THEM TO THIS WORLD?</div>'
      + '<div class="bar" style="justify-content:center;margin:0"><button data-a="save" class="on">SAVE</button><button data-a="discard">DISCARD</button><button data-a="cancel">CANCEL</button></div></div>';
